def transform(grid):
    h, w = len(grid), len(grid[0])
    centers = [(r,c,grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0,3)]
    empty_centers = [(r,c) for r in range(1,h-1) for c in range(1,w-1)
                     if grid[r][c] == 0 and grid[r-1][c] == grid[r+1][c] == grid[r][c-1] == grid[r][c+1] == 3]
    out = [row[:] for row in grid]
    for r,c,color in centers:
        for x in range(w):
            if grid[r][x] != 3: out[r][x] = color
    for r,c,color in centers:
        for y in range(h):
            if grid[y][c] != 3: out[y][c] = color
    # The center-column of each blank cross stays a gap in horizontal beams.
    for r,c in empty_centers:
        for rr,cc,color in centers:
            if rr != r and grid[rr][c] != 3:
                out[rr][c] = 0
    return out
